'use strict';

// MODULES //

import Complex64 from '@stdlib/complex-float32-ctor';
import Float32Array from '@stdlib/array-float32';
import realf from '@stdlib/complex-float32-real';
import imagf from '@stdlib/complex-float32-imag';
import assign from './assign.js';


// VARIABLES //

var out = new Float32Array( 2 );


// MAIN //

/**
* Rounds each component of a single-precision complex floating-point number to the nearest integer.
*
* @param {Complex64} z - complex number
* @returns {Complex64} rounded complex number
*
* @example
* import Complex64 from '@stdlib/complex-float32-ctor';
*
* var v = croundf( new Complex64( -4.2, 5.5 ) );
* // returns <Complex64>[ -4.0, 6.0 ]
*
* v = croundf( new Complex64( 9.99999, 0.1 ) );
* // returns <Complex64>[ 10.0, 0.0 ]
*
* v = croundf( new Complex64( 0.0, 0.0 ) );
* // returns <Complex64>[ 0.0, 0.0 ]
*
* v = croundf( new Complex64( NaN, NaN ) );
* // returns <Complex64>[ NaN, NaN ]
*/
function croundf( z ) {
	assign( realf( z ), imagf( z ), out, 1, 0 );
	return new Complex64( out[ 0 ], out[ 1 ] );
}


// EXPORTS //

export default croundf;
