'use strict';

/**
* Round each component of a single-precision complex floating-point number to the nearest integer.
*
* @module @stdlib/math-base-special-croundf
*
* @example
* import Complex64 from '@stdlib/complex-float32-ctor';
* import croundf from '@stdlib/math-base-special-croundf';
*
* var v = croundf( new Complex64( -4.2, 5.5 ) );
* // returns <Complex64>[ -4.0, 6.0 ]
*
* v = croundf( new Complex64( 9.99999, 0.1 ) );
* // returns <Complex64>[ 10.0, 0.0 ]
*
* v = croundf( new Complex64( 0.0, 0.0 ) );
* // returns <Complex64>[ 0.0, 0.0 ]
*
* v = croundf( new Complex64( NaN, NaN ) );
* // returns <Complex64>[ NaN, NaN ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import assign from './assign.js';
import strided from './strided.js';


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

export default main;

// exports: { "assign": "main.assign", "strided": "main.strided" }
